CREATE TABLE external_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,link_id uuid NOT NULL REFERENCES host_identity_links(id) DEFERRABLE,root text NOT NULL,path text NOT NULL,document_id uuid NOT NULL REFERENCES documents(id) DEFERRABLE,baseline_hash text,baseline_document_revision integer,job_id uuid REFERENCES host_jobs(id) DEFERRABLE,state text NOT NULL DEFAULT 'unread',conflict jsonb,revision integer NOT NULL DEFAULT 1,UNIQUE(owner_id,link_id,root,path));
CREATE TABLE remote_backup_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),link_id uuid NOT NULL REFERENCES host_identity_links(id) DEFERRABLE,root text NOT NULL,cadence text NOT NULL,enabled boolean NOT NULL DEFAULT false,password jsonb NOT NULL,next_at timestamptz NOT NULL,revision integer NOT NULL DEFAULT 1);
CREATE TABLE remote_backups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),plan_id uuid REFERENCES remote_backup_plans(id) DEFERRABLE,plan_revision integer,link_id uuid NOT NULL REFERENCES host_identity_links(id) DEFERRABLE,root text NOT NULL,slot text NOT NULL,content_hash text,archive jsonb,state text NOT NULL DEFAULT 'preparing',chunk_index integer NOT NULL DEFAULT 0,chunk_count integer NOT NULL DEFAULT 0,manifest_revision integer,job_id uuid REFERENCES host_jobs(id) DEFERRABLE,error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,slot));
